import{_ as a,o,c as t,a2 as r}from"./chunks/framework.C2TvIV46.js";const u=JSON.parse('{"title":"Export","description":"","frontmatter":{},"headers":[],"relativePath":"megacrow/export.md","filePath":"megacrow/export.md"}'),l={name:"megacrow/export.md"};function s(i,e,n,d,c,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h1><p>Use <strong>Export</strong> in the toolbar to compile the current Megalo gametype and save it in a chosen binary format. Pick a format from the <strong>Export as</strong> menu.</p><p>All formats are produced from the same compiled variant; only the container and intended use differ.</p><h2 id="formats" tabindex="-1">Formats <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;Formats&quot;">​</a></h2><h3 id="mglo" tabindex="-1"><code>.mglo</code> <a class="header-anchor" href="#mglo" aria-label="Permalink to &quot;`.mglo`&quot;">​</a></h3><p><strong>Best for:</strong> hot reload and HREK / MCC <code>maps/megalo</code> workflows.</p><ul><li>Smallest custom-variant payload (raw Megalo bitstream)</li><li>Drop into your workspace <strong>output folder</strong> (usually <code>maps/megalo</code>) for debug / developer reload</li><li>Does not wrap the variant in a full BLF document</li></ul><p>Use this when iterating on a script and loading it from the game&#39;s megalo maps directory.</p><h3 id="gvar" tabindex="-1"><code>gvar</code> <a class="header-anchor" href="#gvar" aria-label="Permalink to &quot;`gvar`&quot;">​</a></h3><p><strong>Best for:</strong> Xbox 360 matchmaking / debug net commands.</p><ul><li>BLF wrapper aimed at Xbox 360 matchmaking-style loading</li><li>In debug builds, load with <code>net_load_and_use_game_variant</code></li><li>Larger than <code>.mglo</code> because of BLF framing</li></ul><p>Prefer <code>gvar</code> when you specifically need the 360 matchmaking BLF path rather than File Share or MCC save formats.</p><h3 id="mpvr" tabindex="-1"><code>mpvr</code> <a class="header-anchor" href="#mpvr" aria-label="Permalink to &quot;`mpvr`&quot;">​</a></h3><p><strong>Best for:</strong> standard in-game saves, File Share, and Xbox / PC gametype files.</p><ul><li>Standard BLF packaging for Reach custom variants</li><li>Suitable for saving in-game, uploading to File Share, and sharing across Xbox / PC workflows</li><li>The usual “full” gametype file people exchange</li></ul><p>Choose <code>mpvr</code> when you want a normal shareable / loadable gametype file rather than a raw <code>.mglo</code> bitstream.</p><h3 id="autosave-queue-asq" tabindex="-1">Autosave Queue (<code>asq</code>) <a class="header-anchor" href="#autosave-queue-asq" aria-label="Permalink to &quot;Autosave Queue (`asq`)&quot;">​</a></h3><p><strong>Best for:</strong> appearing under <strong>Recent Games</strong> via the autosave queue.</p><ul><li>Writes an Autosave Queue file instead of a standalone variant drop-in</li><li>Place the file where your game expects autosave-queue content so the gametype shows up in Recent Games</li><li>Useful for testing without going through File Share or manual <code>maps/megalo</code> copy for every load path</li></ul><h2 id="choosing-a-format" tabindex="-1">Choosing a format <a class="header-anchor" href="#choosing-a-format" aria-label="Permalink to &quot;Choosing a format&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Format</th></tr></thead><tbody><tr><td>Fastest iterate in <code>maps/megalo</code></td><td><code>.mglo</code></td></tr><tr><td>360 debug <code>net_load_and_use_game_variant</code></td><td><code>gvar</code></td></tr><tr><td>File Share / normal saves / cross-platform</td><td><code>mpvr</code></td></tr><tr><td>Recent Games via autosave queue</td><td>Autosave Queue</td></tr></tbody></table><p>Export uses your current <a href="/MegaloEvolved/beta/docs/megacrow/settings">Settings</a> (author name, compiler profile, strict compiler) when compiling.</p>',22)])])}const p=a(l,[["render",s]]);export{u as __pageData,p as default};
